import Anthropic from '@anthropic-ai/sdk';

const client = new Anthropic();

async function streamAnswer(prompt: string, tools: Anthropic.Tool[]): Promise<string> {
  const stream = client.messages.stream({
    model: 'claude-opus-5',
    max_tokens: 1024,
    tools,
    messages: [{ role: 'user', content: prompt }]
  });

  let text = '';
  for await (const event of stream) {
    if (event.type === 'content_block_delta') {
      text += event.delta.text;
    }
  }
  return text;
}

referenceAnswer:
Narrow on the delta type, not just the event type:

```ts
if (event.type === 'content_block_delta' && event.delta.type === 'text_delta') {
  text += event.delta.text;
}
```

content_block_delta is a union: text_delta carries `text`, input_json_delta carries `partial_json` (a tool call's arguments, accumulated separately and JSON-parsed at content_block_stop), thinking_delta carries `thinking`. Reading `.text` off the others yields undefined, and `text += undefined` writes 'undefined' into the string. TypeScript catches this one if the event is not widened away.

