import OpenAI from 'openai';

const openai = new OpenAI();

type Sentiment = 'positive' | 'negative' | 'neutral';

async function classify(text: string): Promise<Sentiment> {
  const response = await openai.chat.completions.create({
    model: 'gpt-4o',
    max_completion_tokens: 64,
    messages: [
      { role: 'system', content: 'You are a sentiment classifier. Respond with only: positive, negative, or neutral.' },
      { role: 'user', content: text }
    ],
    response_format: { type: 'json_object' }
  });
  return response.choices[0].message.content as Sentiment;
}

referenceAnswer:
JSON mode only guarantees that the output is valid JSON — it does not validate a schema, and it does not leave the model free to answer with a bare word. Either drop response_format and keep the one-word contract, or keep JSON mode and parse the object:

```ts
const parsed = JSON.parse(response.choices[0].message.content ?? '{}');
return parsed.sentiment as Sentiment;
```

If JSON mode stays, the prompt must also describe the object shape, and Structured Outputs with a JSON schema is the stronger option because it constrains the shape rather than just the syntax.

