async function withRetry<T>(
  fn: () => Promise<T>,
  maxRetries = 3
): Promise<T> {
  let lastError: Error;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return __BLANK__ fn();
    } catch (error: unknown) {
      lastError = error as Error;
      const isRateLimit = (error as any)?.status === __BLANK__;
      if (!isRateLimit || attempt === maxRetries) throw error;
      const delay = __BLANK__ ** attempt * 1000;
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
  throw lastError!;
}

async function agentLoop(userMessage: string): Promise<string> {
  const messages: Anthropic.MessageParam[] = [
    { role: 'user', content: userMessage }
  ];

  while (true) {
    const response = await client.messages.create({
      model: 'claude-opus-5',
      max_tokens: 1024,
      tools: TOOLS,
      messages
    });

    messages.push({ role: __BLANK__, content: response.content });

    if (response.stop_reason !== __BLANK__) {
      const textBlock = response.content.find(b => b.type === 'text');
      return textBlock?.type === 'text' ? textBlock.text : '';
    }

    const toolResults: Anthropic.ToolResultBlockParam[] = [];
    for (const block of response.content) {
      if (block.type === 'tool_use') {
        const result = await executeTool(block.name, block.input);
        toolResults.push({ type: 'tool_result', tool_use_id: __BLANK__, content: result });
      }
    }
    messages.push({ role: 'user', content: toolResults });
  }
}

