import { describe, it, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { PriceTag } from './PriceTag';
import { formatPrice } from './formatPrice';

vi.mock('./formatPrice', () => ({
  formatPrice: vi.fn(() => '£1.01')
}));

describe('PriceTag', () => {
  it('rounds a half-penny amount up', () => {
    render(<PriceTag amount={1.005} currency="GBP" />);

    expect(screen.getByText('£1.01')).toBeInTheDocument();
    expect(formatPrice).toHaveBeenCalledWith(1.005, 'GBP');
  });
});

referenceAnswer:
The regression lives in `formatPrice`, and `vi.mock('./formatPrice')` replaces exactly that module. The rendered text comes from the stub, so reverting the fix leaves the suite green: the test has zero mutation sensitivity and is evidence of nothing. The `toHaveBeenCalledWith` assertion is not a rescue either — it proves the component forwards its props, which was never the broken behaviour. Fix: assert against the real function for the boundary input, and keep a separate render test for the wiring only.

```ts
// formatPrice.test.ts - no mock, this is the unit under test
expect(formatPrice(1.005, 'GBP')).toBe('£1.01');

// PriceTag.test.tsx - wiring only, real formatPrice
render(<PriceTag amount={1.005} currency="GBP" />);
expect(screen.getByText('£1.01')).toBeInTheDocument();
```

